import { BadRequestException, Controller, Get, Injectable, Module, PipeTransform, Query } from '@nestjs/common';
import { localeSchema } from './books.contract';

@Injectable()
class BooksService {
  list(locale: 'en' | 'vi') {
    return [{ id: 1, title: locale === 'vi' ? 'Sách mẫu' : 'Sample book' }];
  }
}

class LocalePipe implements PipeTransform<unknown, 'en' | 'vi'> {
  transform(value: unknown): 'en' | 'vi' {
    const result = localeSchema.safeParse(value ?? 'en');
    if (!result.success) throw new BadRequestException({ code: 'VALIDATION_FAILED', field: 'locale' });
    return result.data;
  }
}

@Controller('books')
class BooksController {
  constructor(private readonly books: BooksService) {}
  @Get() list(@Query('locale', new LocalePipe()) locale: 'en' | 'vi') {
    return this.books.list(locale);
  }
}

@Module({ controllers: [BooksController], providers: [BooksService] })
class BooksModule {}
@Module({ imports: [BooksModule] })
export class AppModule {}

