import 'dotenv/config';
import { PrismaMariaDb } from '@prisma/adapter-mariadb';
import { PrismaClient } from './generated/prisma/client';

async function main() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('Set a disposable local DATABASE_URL');
  const prisma = new PrismaClient({ adapter: new PrismaMariaDb(url) });
  try {
    let aborted = false;
    try {
      await prisma.$transaction(async tx => {
        const book = await tx.book.create({ data: { slug: 'rollback-book-en', title: 'Temporary', locale: 'en' } });
        const tag = await tx.tag.upsert({ where: { name: 'rollback-test' }, update: {}, create: { name: 'rollback-test' } });
        await tx.bookTag.create({ data: { bookId: book.id, tagId: tag.id } });
        throw new Error('LAB_ROLLBACK');
      });
    } catch (error) {
      if (!(error instanceof Error) || error.message !== 'LAB_ROLLBACK') throw error;
      aborted = true;
    }
    const partialBook = await prisma.book.findUnique({ where: { slug: 'rollback-book-en' } });
    const partialTag = await prisma.tag.findUnique({ where: { name: 'rollback-test' } });
    console.log({ aborted, partialBook: partialBook !== null, partialTag: partialTag !== null });
  } finally {
    await prisma.$disconnect();
  }
}
main().catch(error => { console.error(error); process.exitCode = 1; });

