import { afterEach, beforeEach, expect, it } from 'vitest';
import request from 'supertest';
import { BadRequestException, CanActivate, Controller, ExecutionContext, ForbiddenException, Get, INestApplication, Module, Post, Body, PipeTransform, UnauthorizedException, UseGuards } from '@nestjs/common';
import { Test } from '@nestjs/testing';
import { z } from 'zod';

const input = z.strictObject({ title: z.string().trim().min(1).max(200), locale: z.enum(['en', 'vi']) });
const books: { id: number; title: string; locale: 'en' | 'vi' }[] = [];
class BookInputPipe implements PipeTransform<unknown, z.output<typeof input>> {
  transform(raw: unknown) {
    const result = input.safeParse(raw);
    if (!result.success) throw new BadRequestException({ code: 'VALIDATION_FAILED', field: 'title' });
    return result.data;
  }
}
class TestEditorGuard implements CanActivate {
  canActivate(context: ExecutionContext) {
    const role = context.switchToHttp().getRequest().headers['x-test-role'];
    if (!role) throw new UnauthorizedException();
    if (role !== 'editor') throw new ForbiddenException();
    return true;
  }
}
@Controller('books')
class TestBooksController {
  @Get() list() { return books; }
  @Post() @UseGuards(TestEditorGuard) create(@Body(new BookInputPipe()) data: z.output<typeof input>) {
    const book = { id: books.length + 1, ...data };
    books.push(book);
    return book;
  }
}
@Module({ controllers: [TestBooksController] })
class TestBooksModule {}
let app: INestApplication;
beforeEach(async () => {
  books.length = 0;
  const moduleRef = await Test.createTestingModule({ imports: [TestBooksModule] }).compile();
  app = moduleRef.createNestApplication();
  app.setGlobalPrefix('api');
  await app.init();
});
afterEach(async () => { await app.close(); });
it('anonymous is 401 even with invalid body', async () => {
  await request(app.getHttpServer()).post('/api/books').send({ title: '' }).expect(401);
});
it('reader is 403', async () => {
  await request(app.getHttpServer()).post('/api/books').set('x-test-role', 'reader').send({ title: 'A', locale: 'en' }).expect(403);
});
it('editor with invalid body is 400', async () => {
  await request(app.getHttpServer()).post('/api/books').set('x-test-role', 'editor').send({ title: '', locale: 'vi' }).expect(400).expect(({ body }) => {
    expect(body).toMatchObject({ code: 'VALIDATION_FAILED', field: 'title' });
  });
});
it('editor with valid body creates a public book', async () => {
  const response = await request(app.getHttpServer()).post('/api/books').set('x-test-role', 'editor').send({ title: 'Sách', locale: 'vi' }).expect(201);
  expect(response.body).toEqual({ id: 1, title: 'Sách', locale: 'vi' });
  await request(app.getHttpServer()).get('/api/books').expect(200, [response.body]);
});

